import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String s = br.readLine();if (s != null && (s.contains("0000000") || s.contains("1111111"))) {System.out.println("YES");} else {System.out.println("NO");}}}